    msgpack_object entry;
    msgpack_object map;
    msgpack_object root;
    msgpack_object chunk;
    msgpack_unpacked result;
    msgpack_unpacker *unp;
    size_t all_used = 0;
    struct msgpack_sbuffer mp_sbuf;
    struct msgpack_packer mp_pck;
    struct flb_in_fw_config *ctx = conn->ctx;

